# Round9: order the final, actually executable market queue.
# Economic mechanism from prvsiyan/The Moon Counts Melons, Apache-2.0,
# https://www.kaggle.com/code/prvsiyan/kaggriculture-frontier-the-moon-counts-melons
# Uses the inherited clone-model objective, NOT the opponent private inventory.
_R9M_PARENT = round8_production_fusion_agent
_R9M_REPORT = {'changes':0,'errors':0}
def round9_final_market_agent(observation,configuration=None):
    if int(observation['step'])==0:
        for key in _R9M_REPORT:_R9M_REPORT[key]=0
    action=_R9M_PARENT(observation,configuration)
    if int(observation['step'])>=216 and _ig_standard(configuration):
        result=_v44y_reorder(observation,action)
        _R9M_REPORT['changes']+=int(result!=action)
        return result
    return action
round9_final_market_agent.telemetry=_R9M_REPORT

_CXD_FROM=720
_ADV_LOOK=4
_ADV_TO=718

# Original Round9: reclaim only a hired worker's finished native day.
# Current and future mandatory physical commands always take precedence.
_R9S_PARENT=round9_final_market_agent
_R9S_STATE={}
_R9S_REPORT={'crew_turns':0,'care':0,'fertilizer':0,'harvest':0,'sales':0,'errors':0}
_R9S_MOVES={'NORTH':(0,-1),'SOUTH':(0,1),'EAST':(1,0),'WEST':(-1,0)}
_R9S_PRODUCT={'COW':'MILK','SHEEP':'WOOL','GOOSE':'EGG'}
_R9S_PERIOD={'COW':2,'SHEEP':3,'GOOSE':1}
_R9S_FIRST={'COW':8,'SHEEP':6,'GOOSE':4}

def _r9s_reservations(obs,native):
    step=int(obs['step']);positions=[list(obs['farms'][obs['player']]['farmer'])]+[list(p) for p in obs['farms'][obs['player']]['hands']]
    reserved=set();busy=set()
    for t in range(step+1,min((step//24+1)*24,719)):
        tape=_IMPL.chassis.routes[2 if t>=648 else native['route']]
        a=tape[t];cmds=[a.get('farmer') or ['PASS']]+list(a.get('hands') or [])
        for i,c in enumerate(cmds[:len(positions)]):
            if c and c!=['PASS']:
                busy.add(i)
                if c[0] in _R9S_MOVES:
                    dx,dy=_R9S_MOVES[c[0]];positions[i]=[max(0,min(9,positions[i][0]+dx)),max(0,min(9,positions[i][1]+dy))]
                elif c[0] in ('CARE','HARVEST','COLLECT_FERTILIZER'):reserved.add((tuple(positions[i]),c[0]))
    return reserved,busy

def _r9s_apply(obs,action):
    step=int(obs['step']);day=step//24;seat=int(obs['player'])
    if day<12 or day>=29 or step%24<8:return action
    farm=obs['farms'][seat];private=obs['private'];native=_IMPL.chassis.players.get(seat)
    if not native or _V219_STATES.get(seat,{}).get('committed'):return action
    state=_R9S_STATE.setdefault(seat,{'day':day,'credit':{},'previous':{}})
    if state['day']!=day:state['day']=day;state['previous']={}
    for actor,past in state['previous'].items():
        if past['step']==step-1 and actor<len(private['inventories']):
            inv=private['inventories'][actor]
            for item in ('MILK','WOOL','EGG','FERTILIZER'):
                gain=max(0,int(inv.get(item,0))-past['stock'].get(item,0))
                if gain:state['credit'][item]=state['credit'].get(item,0)+gain
    state['previous']={}
    cmds=[action.get('farmer') or ['PASS']]+list(action.get('hands') or []);positions=[farm['farmer']]+farm['hands']
    cmds+=[['PASS'] for _ in range(len(positions)-len(cmds))]
    free=[i for i in range(1,len(positions)) if cmds[i]==['PASS']]
    if not free:return action
    reserved,busy=_r9s_reservations(obs,native)
    for i,c in enumerate(cmds):
        if i<len(positions) and c and c[0] in ('CARE','HARVEST','COLLECT_FERTILIZER'):reserved.add((tuple(positions[i]),c[0]))
    stock_total=sum(private['shed'].values())+sum(sum(x.values()) for x in private['inventories'])
    targets=set();changed=False
    for actor in free:
        if actor in busy:continue
        pos=positions[actor];best=None
        for y,row in enumerate(farm['tiles']):
            for x,tile in enumerate(row):
                if not isinstance(tile,dict) or tile.get('animal') not in _R9S_PRODUCT:continue
                site=(x,y);kind=tile['animal'];product=_R9S_PRODUCT[kind]
                distance=abs(pos[0]-x)+abs(pos[1]-y)
                if distance+1>23-step%24:continue
                tasks=[];yield_units=int(tile.get('yield_units',0));pending=int(tile.get('pending_care_bonus',0))
                first=int(tile['placed_day'])+_R9S_FIRST[kind]
                next_yield=first if day<first else day+((_R9S_PERIOD[kind]-(day-first)%_R9S_PERIOD[kind])%_R9S_PERIOD[kind])
                if tile.get('fed_today') and not tile.get('cared_today') and next_yield<30 and yield_units+pending<5:
                    tasks.append(('CARE',float(obs['market']['prices'][product]),0))
                if stock_total<85 and tile.get('fertilizer_available'):
                    tasks.append(('COLLECT_FERTILIZER',float(obs['market']['prices']['FERTILIZER']),1))
                if yield_units>0 and stock_total+yield_units<=85:
                    tasks.append(('HARVEST',.3*yield_units*float(obs['market']['prices'][product]),yield_units))
                for op,value,quantity in tasks:
                    if (site,op) in reserved or site in targets:continue
                    score=value/(distance+1)
                    if best is None or score>best[0]:best=(score,site,op,quantity)
        if best is None:continue
        _,site,op,quantity=best;targets.add(site)
        command=_v219_walk(pos,site) or [op];cmds[actor]=command;changed=True
        _R9S_REPORT['crew_turns']+=1
        if len(command)==1 and command[0]==op:
            _R9S_REPORT[{'CARE':'care','HARVEST':'harvest','COLLECT_FERTILIZER':'fertilizer'}[op]]+=1
            stock_total+=quantity
        state['previous'][actor]={'step':step,'stock':dict(private['inventories'][actor])}
    if not changed:return action
    result=dict(action,farmer=cmds[0],hands=cmds[1:]);market=[list(o) for o in result.get('market',[])]
    # Liquidate credited extra cash crops only. Fertilizer stays available to
    # the parent; its future resource obligations take priority over sale value.
    projected=projected_shed(result,FarmView(obs))
    for item in ('MILK','WOOL','EGG'):
        planned=sum(int(o[2]) for o in market if o and len(o)>=3 and o[:2]==['SELL',item])
        extra=min(state['credit'].get(item,0),max(0,int(projected.get(item,0))-planned))
        if extra>0:
            order=next((o for o in market if o and o[:2]==['SELL',item]),None)
            if order is not None:order[2]+=extra
            elif len(market)<10:market.append(['SELL',item,extra])
            else:continue
            state['credit'][item]-=extra;_R9S_REPORT['sales']+=extra
    result['market']=market
    return result

def round9_slack_agent(observation,configuration=None):
    if int(observation['step'])==0:
        _R9S_STATE.clear()
        for k in _R9S_REPORT:_R9S_REPORT[k]=0
    return _r9s_apply(observation,_R9S_PARENT(observation,configuration))
round9_slack_agent.telemetry=_R9S_REPORT

# Public-state market-pressure experiment. No network or private rival input.
_V10_ADV_HORIZON = 12
_V10_ADV_THRESHOLD = 4
_V10_ADV_REPORT = {'pressure_plans': 0, 'errors': 0}

def _v10_pressure_plan(obs, plan, protected):
    step = int(obs['step']); seat = int(obs['player'])
    stock = _OR2_STATE.get(seat, {}).get('stock', {})
    shops = obs.get('town', {}).get('unlocked_shops', [])
    result = []
    for t, item, quantity in plan:
        if t - step <= _ADV_LOOK and item != protected:
            result.append((t, item, quantity)); continue
        if step < 216:
            continue
        per_tick = 0
        for shop in shops:
            goods = _OR2_SHOPS.get(shop, ())
            if item in goods:
                per_tick += 2 if len(goods) == 1 else 1
        demand = per_tick * sum(x % 4 == 0 for x in range(step, t))
        demand += sum(x % 24 == 0 for x in range(step, t))
        if int(stock.get(item, 0)) >= max(_V10_ADV_THRESHOLD, 2 * demand):
            result.append((t, item, quantity))
            _V10_ADV_REPORT['pressure_plans'] += 1
    return result

def _adv_apply(obs,action):
    step=int(obs['step']);player=int(obs['player'])
    if step%24==23 or not _ADV_FROM<=step<_ADV_TO:return action
    native=_IMPL.chassis.players[player];debts=native['sell_state'].setdefault('r36_debts',{})
    plan=[];first=None
    for off in range(1,_V10_ADV_HORIZON+1):
        t=step+off
        if t>718:break
        for o in _adv_future(player,t):
            if not o or len(o)<3:continue
            if first is None:first=o
            if o[0]=='SELL' and o[1] in _ADV_ITEMS:
                try:q=max(0,int(o[2]))
                except Exception:q=0
                if _ADV_SUBTRACT_DEBTS:q-=debts.get(t,{}).get(o[1],0)   # already reserved by the sale-reservation layer
                if q>0:plan.append((t,o[1],q))
    protected=first[1] if _ADV_PROTECT and first is not None and first[0]=='SELL' else None
    plan=_v10_pressure_plan(obs,plan,protected)
    if not plan:return action
    market=[list(o) for o in (action.get('market') or [])]
    if any(len(o)>1 and o[0]=='BUY_PRODUCT' for o in market):return action
    stock=projected_shed(action,FarmView(obs))
    selling={}
    for o in market:
        if len(o)>=3 and o[0]=='SELL':
            try:selling[o[1]]=selling.get(o[1],0)+max(0,int(o[2]))
            except Exception:return action
    commands=[action.get('farmer') or ['PASS'],*(action.get('hands') or [])]
    picked={c[1] for c in commands if len(c)>1 and c[0]=='PICKUP'}
    prices=obs['market']['prices'];added=0;extra=[];booked=[]
    for item in sorted({it for _,it,_ in plan},key=lambda it:-int(prices.get(it,0))):
        if item in picked or int(prices.get(item,0))<2:continue
        avail=int(stock.get(item,0))-selling.get(item,0)
        if avail<1:continue
        hit=next((o for o in market if len(o)>=3 and o[0]=='SELL' and o[1]==item),None)
        if hit is None and len(market)+len(extra)>=10:continue
        n=0
        for t,it,q in plan:
            if it!=item or avail<=0:continue
            take=min(q,avail);booked.append((t,item,take));n+=take;avail-=take
        if n<1:continue
        if hit is not None:hit[2]=int(hit[2])+n
        else:extra.append(['SELL',item,n])
        added+=n
    if not added:return action
    for t,item,take in (booked if _ADV_BOOK else []):
        d=debts.setdefault(t,{});d[item]=d.get(item,0)+take
    _ADV_REPORT['adv_turns']+=1;_ADV_REPORT['adv_units']+=added
    return dict(action,market=extra+market)
_V10_PARENT=round9_slack_agent
def v10_pressure_agent(observation,configuration=None):
    if int(observation["step"])==0:
        for key in _V10_ADV_REPORT:_V10_ADV_REPORT[key]=0
    return _V10_PARENT(observation,configuration)
v10_pressure_agent.telemetry=_V10_ADV_REPORT
agent=v10_pressure_agent
kaggle_submission_agent=v10_pressure_agent

# Align the inherited public-flow observer with the final executable sell list.
# Rival stock remains an estimate, not access to hidden rival inventories.
_V10_LEDGER_PARENT = v10_pressure_agent
_V10_LEDGER_REPORT = {'corrected_items': 0, 'quantity_difference': 0}

def v10_ledger_agent(observation, configuration=None):
    if int(observation['step']) == 0:
        for key in _V10_LEDGER_REPORT:
            _V10_LEDGER_REPORT[key] = 0
    action = _V10_LEDGER_PARENT(observation, configuration)
    state = _OR2_STATE.get(int(observation['player']), {})
    previous = state.get('prev')
    if not previous or previous.get('step') != int(observation['step']):
        return action
    available = projected_shed(action, FarmView(observation))
    own = previous.setdefault('own', {})
    for item in _ADV_ITEMS:
        quantity = sum(max(0, int(o[2])) for o in action.get('market', [])[:10]
                       if len(o) >= 3 and o[:2] == ['SELL', item])
        sold = min(max(0, int(available.get(item, 0))), quantity)
        if sold != int(own.get(item, 0)):
            _V10_LEDGER_REPORT['corrected_items'] += 1
            _V10_LEDGER_REPORT['quantity_difference'] += sold - int(own.get(item, 0))
        own[item] = sold
    return action
v10_ledger_agent.telemetry = _V10_LEDGER_REPORT
agent = v10_ledger_agent
kaggle_submission_agent = v10_ledger_agent

